  20     constructor(
  21         @inject(IRetrievalServiceToken) private retrievalService: IRetrievalService
  22     ) {}
  23 
  24     async generateText(prompt: string, options?: any): Promise<Result<string, AiError>> {
  25         try {
  26             const result = await ai.generate({
  27                 prompt,
  28                 ...options
  29             });
  30             return Result.ok(result.text);
  31         } catch (error: any) {
  32             return Result.fail(AiError.generationFailed(error.message));
  33         }
  34     }
  35 
  36     /**
  37      * Post-processes AI output to remove common conversational prefixes from small models.
  38      */
  39     private cleanAiOutput(text: string): string {
  40         if (!text) return text;
  41         
  42         // List of common conversational prefixes used by small models like Gemma/Phi
  43         const patterns = [
  44             /^Sure,? (here is|here's) the [^:]+:?\s*/i,
  45             /^Sure,? here (is|'s) [^:]+:?\s*/i,
  46             /^Certainly!? [^:]+:?\s*/i,
  47             /^As requested,? [^:]+:?\s*/i,
  48             /^I have [^:]+ below:?\s*/i,
  49             /^The following is [^:]+:?\s*/i,
  50             /^Ok,? (here is|here's) [^:]+:?\s*/i,
  51             /^Below is the [^:]+:?\s*/i,
  52             /^Sure,? I can [^:]+:?\s*/i,
  53         ];
  54 
  55         let cleaned = text.trim();
  56         // Run multiple passes to catch nested filler
  57         for (let i = 0; i < 2; i++) {
  58             for (const pattern of patterns) {
  59                 cleaned = cleaned.replace(pattern, '');
  60             }
  61             cleaned = cleaned.trim();
  62         }
  63         return cleaned;
  64     }
  65 
  66     async runFlow<TInput, TOutput>(flow: any, input: TInput, flowName?: string): Promise<Result<TOutput, AiError>> {
  67         const primaryModel = flowName ? selectModel({ flowName }) : null;
  68         const modelsToTry = primaryModel 
  69             ? [primaryModel, OLLAMA_MODELS.PHI3_MINI, OLLAMA_MODELS.GEMMA_2B] 
  70             : [null]; // null means direct execution without queue manager model selection
  71         
  72         // Remove duplicates while preserving order
  73         const uniqueModels = Array.from(new Set(modelsToTry));
  74         let lastError: any;
  75 
  76         for (const model of uniqueModels) {
  77             try {
  78                 let result: any;
  79                 if (!model) {
  80                     result = await flow(input);
  81                 } else {
  82                     result = await executeWithQueue(
  83                         generateRequestId(),
  84                         model,
  85                         flowName,
  86                         () => flow(input)
  87                     );
  88                 }
  89 
  90                 // Post-process string outputs to remove conversational filler
  91                 if (result && typeof result === 'object') {
  92                     for (const key in result) {
  93                         if (typeof result[key] === 'string') {
  94                             result[key] = this.cleanAiOutput(result[key]);
  95                         }
  96                     }
  97                 } else if (typeof result === 'string') {
  98                     result = this.cleanAiOutput(result);
  99                 }
 100 
 101                 return Result.ok(result as TOutput);
 102             } catch (error: any) {
 103                 lastError = error;
 104                 console.warn(`Flow execution failed for model ${model || 'default'} in ${flowName || 'unnamed flow'}. Error: ${error.message}`);
 105                 
 106                 // If it's a validation error or user error, don't retry with other models
 107                 if (error.message?.includes('validation') || error.status === 400) {
 108                     break;
 109                 }
 110                 
 111                 // Continue to next model in the tiered fallback list
 112                 continue;
 113             }
 114         }
 115 
 116         return Result.fail(AiError.generationFailed(lastError?.message || 'Flow execution failed after all fallback attempts'));
 117     }
 118 
 119     async retrieveContext(query: string, options?: RetrievalOptions): Promise<Result<RetrievalResult, AiError>> {
 120         return this.retrievalService.retrieveContext(query, options);
 121     }
 122 
 123     async generateChapterWithRAG(input: any): Promise<Result<any, AiError>> {
 124         try {
 125             const result = await generateChapterContentWithRAG(input);
 126             return Result.ok(result);
 127         } catch (error: any) {
 128             return Result.fail(AiError.generationFailed(error.message));
 129         }
 130     }
 131 
 132     async generateSectionWithRAG(input: any): Promise<Result<any, AiError>> {
 133         try {
 134             const result = await generateReportSectionWithRAG(input);
 135             return Result.ok(result);
 136         } catch (error: any) {
 137             return Result.fail(AiError.generationFailed(error.message));
 138         }
 139     }
 140 }
