    'ai-researcher': 'aiResearch',
    'generate-plant-uml': 'generatePlantUML',
    'image-to-text': 'imageToText',
    'generate-citation': 'generateCitation',
    'generate-toc': 'generateTOC',
    'literature-review-generator': 'generateLitReview',
    'lecture-generator': 'generateLecture',
    'sentence-structure-checker': 'sentenceStructureCheck',
    'topic-explainer': 'explainTopic',
    'generate-ideas': 'generateIdeas',
    'generate-ui-description': 'generateUIDescription',
    'generate-session-plan': 'generateSessionPlan',
    'solve-assignments': 'solveAssignments',
    'generate-project-blueprint': 'generateProjectBlueprint',
    'proofread-document': 'proofreadDocument',
    'analyze-context': 'analyzeContext',
    'check-paper-quality': 'checkPaperQuality',
    'improve-markdown': 'improveMarkdown',
    'generate-project-doc': 'generateProjectDoc',
    'rewrite-to-markdown': 'rewriteToMarkdown',
    'write-tech-spec': 'writeTechSpec',
    'create-presentation': 'createPresentation'
};

@injectable()
export class N8nAiService implements IAiService {
    private readonly timeout = 300000; // 300 seconds (5 minutes)

    private async callWebhook(body: any): Promise<Result<any, AiError>> {
        if (!n8nConfig.webhookUrl) {
            return Result.fail(AiError.internal("n8n Webhook URL is not configured."));
        }

        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), this.timeout);

        try {
            const response = await fetch(n8nConfig.webhookUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(body),
                signal: controller.signal
            });

            clearTimeout(timeoutId);

            if (!response.ok) {
                const errorText = await response.text();
                return Result.fail(AiError.generationFailed(`n8n error (${response.status}): ${errorText || response.statusText}`));
            }

            const data = await response.json();

            // Handle n8n standardized error response if present
            if (data.success === false) {
                return Result.fail(AiError.generationFailed(data.error || "Unknown n8n error"));
            }

            return Result.ok(data);
        } catch (error: any) {
            clearTimeout(timeoutId);
            if (error.name === 'AbortError') {
                return Result.fail(AiError.generationFailed("n8n request timed out after 300s."));
            }
            return Result.fail(AiError.generationFailed(error.message));
        }
    }

    async generateText(prompt: string, options?: any): Promise<Result<string, AiError>> {
        const result = await this.callWebhook({
            action: 'generateText',
            prompt,
            options
        });

        if (result.isFailure) return Result.fail(result.getError()!);

        const data = result.getValue();
        return Result.ok(data.text || "");
    }

    async runFlow<TInput, TOutput>(flow: any, input: TInput, flowName?: string): Promise<Result<TOutput, AiError>> {
        const n8nAgentName = flowName ? (N8N_FLOW_MAP[flowName] || flowName) : 'general';

        const result = await this.callWebhook({
            action: 'runFlow',
            flowName: n8nAgentName,
            input
        });

        if (result.isFailure) return Result.fail(result.getError()!);

        const data = result.getValue();
        // n8n agents return text directly or as part of an object depending on the flow
        // The registry expects the TOutput which is usually the 'text' field or the whole object for JSON tools
        if (data.text && !data.issues && !data.aiProbability && !data.analysis) {
             return Result.ok(data.text as unknown as TOutput);
        }

        return Result.ok(data as unknown as TOutput);
    }

    async retrieveContext(query: string, options?: RetrievalOptions): Promise<Result<RetrievalResult, AiError>> {
        const result = await this.callWebhook({
            action: 'retrieveContext',
            query,
            options
        });

        if (result.isFailure) return Result.fail(result.getError()!);
        return Result.ok(result.getValue() as RetrievalResult);
    }

    async generateChapterWithRAG(input: any): Promise<Result<any, AiError>> {
        const result = await this.callWebhook({
            action: 'generateChapterWithRAG',
            input
        });

        if (result.isFailure) return Result.fail(result.getError()!);
        return Result.ok(result.getValue());
    }

    async generateSectionWithRAG(input: any): Promise<Result<any, AiError>> {
        const result = await this.callWebhook({
            action: 'generateSectionWithRAG',
            input
        });

        if (result.isFailure) return Result.fail(result.getError()!);
        return Result.ok(result.getValue());
    }
}

