 189                 prompt: typeof input === 'object' ? JSON.stringify(input) : String(input),
 190                 input,
 191             });
 192 
 193             if (!result.isSuccess) return Result.fail(result.error!);
 194             const text = result.getValue()?.text;
 195             if (typeof text === 'string') {
 196                 return Result.ok(this.cleanAiOutput(text) as unknown as TOutput);
 197             }
 198             return Result.ok(text as TOutput);
 199         }
