 274 
 275     private cleanAiOutput(text: string): string {
 276         if (!text) return text;
 277 
 278         const patterns = [
 279             /^Sure,? (here is|here's) the [^:]+:?\s*/i,
 280             /^Sure,? here (is|'s) [^:]+:?\s*/i,
 281             /^Certainly!? [^:]+:?\s*/i,
 282             /^As requested,? [^:]+:?\s*/i,
 283             /^I have [^:]+ below:?\s*/i,
 284             /^The following is [^:]+:?\s*/i,
 285             /^Ok,? (here is|here's) [^:]+:?\s*/i,
 286             /^Below is the [^:]+:?\s*/i,
 287             /^Sure,? I can [^:]+:?\s*/i,
 288         ];
 289 
 290         let cleaned = text.trim();
 291         for (let i = 0; i < 2; i++) {
 292             for (const pattern of patterns) {
 293                 cleaned = cleaned.replace(pattern, '');
 294             }
 295             cleaned = cleaned.trim();
 296         }
 297         return cleaned;
 298     }
